/* Dhad Studio - Cluster Mode Entry Point */
// Forks one worker per CPU core. Each worker runs src/index.js

const cluster = require('cluster');
const os = require('os');

let logger;
try { logger = require('./utils/logger').logger; } catch (_) { logger = console; }

const NUM_WORKERS = process.env.WEB_CONCURRENCY || os.cpus().length;
// H8: MemoryStore rate-limits/lockouts/blacklists diverge across workers.
// Without REDIS_URL there is no shared state, so force a single worker
// (fail-safe) unless the operator explicitly sets WEB_CONCURRENCY.
const EFFECTIVE_WORKERS = process.env.REDIS_URL ? NUM_WORKERS : (process.env.WEB_CONCURRENCY || 1);

if (cluster.isPrimary) {
  if (!process.env.REDIS_URL) {
    logger.warn('[CLUSTER] No REDIS_URL — running single worker to keep rate-limit/lockout state consistent. Set WEB_CONCURRENCY + REDIS_URL to scale.');
  }
  logger.info(`[CLUSTER] Primary ${process.pid} — starting ${EFFECTIVE_WORKERS} workers`);

  for (let i = 0; i < EFFECTIVE_WORKERS; i++) {
    cluster.fork();
  }

  let ready = 0;
  cluster.on('message', (worker, msg) => {
    if (msg === 'ready') {
      ready++;
      if (ready === EFFECTIVE_WORKERS) {
        logger.info(`[CLUSTER] All ${EFFECTIVE_WORKERS} workers ready.`);
      }
    }
  });

  cluster.on('exit', (worker, code, signal) => {
    logger.error(`[CLUSTER] Worker ${worker.process.pid} died (${signal || code}). Restarting...`);
    cluster.fork();
  });

  process.on('SIGTERM', () => {
    for (const id in cluster.workers) cluster.workers[id].process.kill('SIGTERM');
  });
  process.on('SIGINT', () => {
    for (const id in cluster.workers) cluster.workers[id].process.kill('SIGINT');
  });

} else {
  // Signal to index.js that it should start the server
  process.env.DHAD_START_SERVER = '1';
  require('./index');
}

